<?php declare(strict_types=1);use FastWebsite\Core\View;?>
<section class="page-title-hero"><div class="shell"><p class="eyebrow"><?=View::escape(View::setting($siteContent??[],'facilities.eyebrow','Research infrastructure'))?></p><h1><?=View::escape(View::setting($siteContent??[],'facilities.title','Facilities and equipment'))?></h1><p class="lead"><?=View::escape(View::setting($siteContent??[],'facilities.introduction','Discover FAST laboratories, workshops, specialist facilities, and research equipment.'))?></p></div></section><section class="section"><div class="shell"><h2>Facilities</h2><?php if($facilities===[]):?><div class="public-empty"><p>Published research facilities will appear here.</p></div><?php else:?><div class="feature-grid"><?php foreach($facilities as$f):?><article><p class="eyebrow"><?=View::escape(ucwords(str_replace('_',' ',$f['facility_type'])))?></p><h3><?=View::escape($f['name'])?></h3><p><?=View::escape($f['description']??'')?></p><p class="card-meta"><a href="<?=View::escape($baseUrl)?>research/<?=View::escape($f['research_unit_slug'])?>"><?=View::escape($f['research_unit_name'])?></a></p></article><?php endforeach;?></div><?php endif;?></div></section><section class="section research-metadata-section"><div class="shell"><h2>Equipment</h2><?php if($equipment===[]):?><div class="public-empty"><p>Publicly available equipment will appear here.</p></div><?php else:?><div class="feature-grid"><?php foreach($equipment as$e):?><article><p class="eyebrow"><?=View::escape(ucfirst($e['availability_status']))?></p><h3><?=View::escape($e['name'])?></h3><p><?=View::escape($e['capabilities']??'')?></p><p class="card-meta"><?=View::escape(implode(' · ',array_filter([$e['manufacturer'],$e['model'],$e['facility_name']])))?></p><?php if($e['external_use_allowed']):?><strong>External use may be available</strong><?php endif;?></article><?php endforeach;?></div><?php endif;?></div></section>
